<script setup lang="ts">import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'; import * as echarts from 'echarts'; import MonthPicker from '@/components/MonthPicker.vue'; import { categoryService } from '@/services/categoryService'; import { recordService } from '@/services/recordService'; import { categoryExpenseTotals } from '@/services/statistics'; import { currentMonth } from '@/utils/date'; import { formatMoney } from '@/utils/money'; import type { Category, RecordItem } from '@/types'; const month = ref(currentMonth()); const records = ref<RecordItem[]>([]); const categories = ref<Category[]>([]); const chart = ref<HTMLElement>(); let instance: echarts.ECharts | undefined; const expense = computed(() => records.value.filter(r => r.type === 'expense').reduce((a,r) => a+r.amount,0)); const income = computed(() => records.value.filter(r => r.type === 'income').reduce((a,r) => a+r.amount,0)); const rank = computed(() => categoryExpenseTotals(records.value, categories.value)); function draw() { if (!chart.value) return; const tokens = getComputedStyle(document.documentElement); const accent = tokens.getPropertyValue('--accent').trim(); const muted = tokens.getPropertyValue('--muted').trim(); const line = tokens.getPropertyValue('--line').trim(); const surface = tokens.getPropertyValue('--surface').trim(); instance?.dispose(); instance = echarts.init(chart.value); const daily = new Map<string, number>(); records.value.filter(r=>r.type==='expense').forEach(r=>daily.set(r.date,(daily.get(r.date)||0)+r.amount)); instance.setOption({ backgroundColor:'transparent', grid:{left:42,right:14,top:30,bottom:30}, tooltip:{trigger:'axis',backgroundColor:surface,borderColor:line,textStyle:{color:tokens.getPropertyValue('--text').trim()}}, xAxis:{type:'category',data:[...daily.keys()].map(d=>d.slice(8)),axisLine:{lineStyle:{color:line}},axisTick:{show:false},axisLabel:{color:muted}}, yAxis:{type:'value',axisLine:{show:false},axisTick:{show:false},splitLine:{lineStyle:{color:line}},axisLabel:{color:muted,formatter:(v:number)=>`¥${v/100}`}}, series:[{type:'line',smooth:true,data:[...daily.values()],showSymbol:false,areaStyle:{color:accent,opacity:.15},lineStyle:{color:accent,width:3},itemStyle:{color:accent}}] }) } async function load() { [records.value,categories.value] = await Promise.all([recordService.list({month:month.value}),categoryService.list()]); await nextTick(); draw() } onMounted(load); onBeforeUnmount(()=>instance?.dispose())</script>
<template><header class="page-head"><h1>统计</h1><MonthPicker v-model="month" @update:model-value="load" /></header><div class="stat-cards"><div><small>月支出</small><strong class="expense">{{ formatMoney(expense) }}</strong></div><div><small>月收入</small><strong class="income">{{ formatMoney(income) }}</strong></div></div><section class="chart-card"><h2>每日支出趋势</h2><div ref="chart" class="chart"></div></section><section class="section"><h2>分类金额排行</h2><div class="list-card rank"><div v-for="(item,index) in rank" :key="item.category?.id"><span>{{ index + 1 }}</span><i>{{ item.category?.icon }}</i><strong>{{ item.category?.name || '已删除分类' }}</strong><b>{{ formatMoney(item.amount) }}</b></div><p v-if="!rank.length" class="empty">暂无支出数据</p></div></section></template>
